\begin{tikzpicture}[x=0.85cm,y=0.85cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{baseTwo}{HTML}{268CFF}
\definecolor{baseThree}{HTML}{EF6068}
\path[use as bounding box] (-2.5,-2.5) rectangle (7.2,5.2);
\draw[black,line width=0.5pt,->] (-2.2,0)--(6.7,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-2.2)--(0,4.8) node[above] {$y$};
\draw[black,dashed,line width=0.4pt] (-2,-2)--(4.4,4.4);
\node[rotate=45,above] at (-1.35,-1.35) {$y=x$};
\draw[baseTwo,line width=0.8pt] plot[domain=-2.1:2.2,samples=100] (\x,{pow(2,\x)});
\draw[baseThree,line width=0.8pt] plot[domain=-2.1:1.4,samples=100] (\x,{pow(3,\x)});
\draw[baseTwo,line width=0.8pt,densely dashed] plot[domain=0.22:6.2,samples=160] (\x,{ln(\x)/ln(2)});
\draw[baseThree,line width=0.8pt,densely dashed] plot[domain=0.09:6.2,samples=160] (\x,{ln(\x)/ln(3)});
\fill[black] (0,1) circle (1.2pt) (1,0) circle (1.2pt);
\node[left] at (0,1) {\special{dvisvgm:raw <g data-graph-text="tick">}$1$\special{dvisvgm:raw </g>}};
\node[below] at (1,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$1$\special{dvisvgm:raw </g>}};
\node[baseThree,above] at (1.35,4.7) {$y=3^x$};
\node[baseTwo,right] at (2.2,4.5) {$y=2^x$};
\node[baseTwo,above] at (5.2,2.5) {$y=\log_2 x$};
\node[baseThree,below] at (5.2,1.45) {$y=\log_3 x$};
\end{tikzpicture}
